var acervo=[],consumiveis=[],calendario=[],entidades=[],pontos=[];
var _nacaoAtiva='';

function irPara(sec,btn){
  document.querySelectorAll('.section').forEach(function(s){s.classList.remove('active');});
  var el=document.getElementById('sec-'+sec);
  if(el)el.classList.add('active');
  document.querySelectorAll('.tab,.nav-btn').forEach(function(b){b.classList.remove('active');});
  if(btn)btn.classList.add('active');
  else{document.querySelectorAll('.tab,.nav-btn').forEach(function(b){if((b.getAttribute('onclick')||'').indexOf("'"+sec+"'")>=0)b.classList.add('active');});}
}
function fillNum(id,v){var el=document.getElementById(id);if(!el)return;el.classList.remove('skeleton','skel-num');el.textContent=v;}
function fecharModal(){document.getElementById('modal-bg').classList.remove('aberto');}
function nslug(n){if(!n)return'';var s=n.toLowerCase();if(s.includes('ok'))return'ok';if(s.includes('repor'))return'repor';if(s.includes('alerta'))return'alerta';if(s.includes('urgente'))return'urgente';return'';}

async function carregarHome(){
  try{
    var r=await Promise.race([fetch(GS+'?acao=datas-mes'),new Promise(function(_,rej){setTimeout(function(){rej(new Error('t'));},30000);})]);
    var j=await r.json();if(!j.ok)return;
    var html='';
    if(j.aniversariantes&&j.aniversariantes.length){html+='<div style="margin-bottom:10px"><strong style="color:var(--ouro);font-size:11px">&#127874; ANIVERSARIANTES<\/strong><br>';j.aniversariantes.forEach(function(a){html+='<div style="font-size:13px;padding:4px 0;border-bottom:1px solid rgba(255,255,255,.04)">'+a.nome+' &#8212; '+a.data+'<\/div>';});html+='<\/div>';}
    if(j.festas&&j.festas.length){html+='<div><strong style="color:var(--ouro);font-size:11px">&#11088; FESTAS DO M&#202;S<\/strong><br>';j.festas.forEach(function(f){html+='<div style="font-size:13px;padding:4px 0;border-bottom:1px solid rgba(255,255,255,.04)">'+f.entidade+' &#8212; '+f.data+'<\/div>';});html+='<\/div>';}
    document.getElementById('home-eventos-lista').innerHTML=html||'<span style="font-style:italic">Nenhum evento este m&#234;s.<\/span>';
  }catch(e){document.getElementById('home-eventos-lista').innerHTML='<span style="font-style:italic">Nenhum evento este m&#234;s.<\/span>';}
}
async function carregarAcervo(){
  try{
    var r=await Promise.race([fetch(GS+'?acao=acervo-listar'),new Promise(function(_,rej){setTimeout(function(){rej(new Error('t'));},30000);})]);
    var j=await r.json();
    if(j.ok){acervo=j.itens||[];var cats=[...new Set(acervo.map(function(i){return i.categoria||''}).filter(Boolean))].sort();var sel=document.getElementById('acervo-cat');cats.forEach(function(c){var o=document.createElement('option');o.value=c;o.textContent=c;sel.appendChild(o);});renderAcervo();}
  }catch(e){document.getElementById('acervo-lista').innerHTML='<div class="empty">N&#227;o foi poss&#237;vel carregar.<\/div>';}
}
async function carregarConsumiveis(){
  try{
    var r=await Promise.race([fetch(GS+'?acao=consumiveis-listar'),new Promise(function(_,rej){setTimeout(function(){rej(new Error('t'));},30000);})]);
    var j=await r.json();
    if(j.ok){
      consumiveis=j.itens||[];
      var ok=0,repor=0,alerta=0,urgente=0;
      consumiveis.forEach(function(i){var sl=nslug(i.nivel||'');if(sl==='ok')ok++;else if(sl==='repor')repor++;else if(sl==='alerta')alerta++;else urgente++;});
      fillNum('cnt-ok',ok);fillNum('cnt-repor',repor);fillNum('cnt-alerta',alerta);fillNum('cnt-urgente',urgente);
      var cats=[...new Set(consumiveis.map(function(i){return i.categoria||''}).filter(Boolean))].sort();
      var sel=document.getElementById('csm-cat');cats.forEach(function(c){var o=document.createElement('option');o.value=c;o.textContent=c;sel.appendChild(o);});
      renderConsumiveis();
    }
  }catch(e){['cnt-ok','cnt-repor','cnt-alerta','cnt-urgente'].forEach(function(id){fillNum(id,'--');});document.getElementById('csm-lista').innerHTML='<div class="empty">N&#227;o foi poss&#237;vel carregar.<\/div>';}
}
