var MP={
  lista:[],idx:-1,tocando:false,ytReady:false,player:null,timer:null,
  setLista:function(l){MP.lista=l;},
  idxDe:function(id){for(var i=0;i<MP.lista.length;i++){if(MP.lista[i].id===id)return i;}return -1;},
  tocar:function(id){
    var i=MP.idxDe(id);
    if(i<0){var p=pontos.find(function(x){return x.id===id;});if(!p||!p.youtube)return;MP.lista=[p];i=0;}
    MP.idx=i;var p=MP.lista[i];
    var ytm=p.youtube.match(/(?:v=|youtu\.be\/)([A-Za-z0-9_\-]{11})/);if(!ytm)return;
    document.getElementById('mp-nome').textContent=p.nome;
    document.getElementById('mp-ent').textContent=p.entidade;
    document.getElementById('mini-player').classList.add('ativo');
    var wrap=document.getElementById('yt-hidden');wrap.innerHTML='<div id="yt-iframe"><\/div>';
    if(window.YT&&window.YT.Player){MP._criar(ytm[1]);}
    else{var t=document.createElement('script');t.src='https://www.youtube.com/iframe_api';document.head.appendChild(t);window._ytVid=ytm[1];}
  },
  _criar:function(vid){
    MP.player=new YT.Player('yt-iframe',{videoId:vid,playerVars:{autoplay:1,controls:0},events:{
      onReady:function(){MP.ytReady=true;MP.tocando=true;MP._ui();},
      onStateChange:function(e){if(e.data===YT.PlayerState.ENDED)MP.proximo();if(e.data===YT.PlayerState.PLAYING){MP.tocando=true;MP._ui();}if(e.data===YT.PlayerState.PAUSED){MP.tocando=false;MP._ui();}}
    }});
  },
  pausePlay:function(){if(!MP.player||!MP.ytReady)return;if(MP.tocando)MP.player.pauseVideo();else MP.player.playVideo();},
  proximo:function(){if(MP.lista.length)MP.tocar(MP.lista[(MP.idx+1)%MP.lista.length].id);},
  anterior:function(){if(MP.lista.length)MP.tocar(MP.lista[(MP.idx-1+MP.lista.length)%MP.lista.length].id);},
  fechar:function(){if(MP.player&&MP.ytReady)MP.player.stopVideo();MP.tocando=false;MP.idx=-1;document.getElementById('mini-player').classList.remove('ativo');clearInterval(MP.timer);document.getElementById('mp-prog').style.width='0%';},
  _ui:function(){
    document.getElementById('mp-play').innerHTML=MP.tocando?'&#9646;&#9646;':'&#9654;';
    clearInterval(MP.timer);
    MP.timer=setInterval(function(){
      if(!MP.player||!MP.ytReady)return;
      try{var d=MP.player.getDuration(),c=MP.player.getCurrentTime();
        if(d>0){document.getElementById('mp-prog').style.width=(c/d*100)+'%';
          var fm=function(s){return Math.floor(s/60)+':'+(Math.floor(s%60)<10?'0':'')+Math.floor(s%60);};
          document.getElementById('mp-tempo').textContent=fm(c)+' / '+fm(d);}
      }catch(e){}
    },500);
  }
};
function onYouTubeIframeAPIReady(){if(window._ytVid){MP._criar(window._ytVid);window._ytVid=null;}}
function mpSeek(e){if(!MP.player||!MP.ytReady)return;var b=document.getElementById('mp-prog').parentElement;MP.player.seekTo((e.clientX-b.getBoundingClientRect().left)/b.offsetWidth*MP.player.getDuration(),true);}

