function carregarEntidades(){
  var STATIC=ENTIDADES_STATIC;
  entidades=STATIC;
  _buildEntTabs();
  renderEntidades();
  try{fetch(GS+'?acao=entidades-listar').then(function(r){return r.json();}).then(function(j){if(j.ok&&j.itens&&j.itens.length){entidades=j.itens;_buildEntTabs();renderEntidades();}}).catch(function(){});}catch(e){}
}
function _buildEntTabs(){
  var nacoes=new Set();
  entidades.forEach(function(e){(e.nacao||'').split('/').forEach(function(p){if(p.trim())nacoes.add(p.trim());});});
  var sorted=[...nacoes].sort();
  var wrap=document.querySelector('.ent-tabs');if(!wrap)return;
  var html='';
  html+='<button class="ent-tab'+(_nacaoAtiva===''?' active':'')+'" data-nacao="" onclick="setNacao(this)">Todos<\/button>';
  sorted.forEach(function(n){
    html+='<button class="ent-tab'+(_nacaoAtiva===n?' active':'')+'" data-nacao="';
    html+=n;
    html+='" onclick="setNacao(this)">';
    html+=n;
    html+='<\/button>';
  });
  wrap.innerHTML=html;
}

var CATALOG_PONTOS=null;

var _plLista=[],_plIdx=-1,_plTimer=null,_plTocando=false;
function getListaPontos(){var ent=document.getElementById('pt-ent').value,q=(document.getElementById('pt-busca').value||'').toLowerCase(),lista=[];Object.entries(CATALOG_PONTOS).forEach(function(e){var k=e[0],v=e[1];if(ent&&k!==ent)return;v.forEach(function(p){if(!q||(p.nome||'').toLowerCase().includes(q))lista.push({nome:p.nome,url:p.url,ent:k});});});return lista;}
function renderPontos(){
  var ent=(document.getElementById('pt-ent')||{}).value||'',q=(document.getElementById('pt-busca').value||'').toLowerCase();
  var wrap=document.getElementById('pt-content');if(!wrap)return;
  var keys=ent?[ent]:Object.keys(CATALOG_PONTOS).sort();
  var total=0,html='';
  keys.forEach(function(k){
    var items=(CATALOG_PONTOS[k]||[]).filter(function(p){return !q||(p.nome||'').toLowerCase().includes(q);});
    if(!items.length)return;total+=items.length;
    html+='<div class="grupo-wrap"><div class="grupo-titulo">'+k+'<\/div>';
    items.forEach(function(p,i){
      var eid='ac'+i+k.replace(/[^a-z0-9]/gi,'');
      html+='<div class="audio-card" id="'+eid+'" data-url="'+encodeURIComponent(p.url)+'" data-nome="'+p.nome.replace(/"/g,'&quot;')+'" data-ent="'+k.replace(/"/g,'&quot;')+'" onclick="_acClick(this)"><div class="ac-num">'+(i+1)+'<\/div><div class="ac-play"><span>&#9654;<\/span><\/div><div class="ac-nome">'+p.nome+'<\/div><\/div>';
    });
    html+='<\/div>';
  });
  if(!html)html='<div class="empty" style="grid-column:1/-1"><p>&#127925; Nenhum ponto encontrado.<\/p><\/div>';
  wrap.innerHTML=html;
  document.getElementById('pt-count').textContent=total+' ponto'+(total!==1?'s':'');
  _plLista=getListaPontos();
}
function _acClick(el){plTocar(decodeURIComponent(el.dataset.url),el.dataset.nome,el.dataset.ent);}
function plTocar(url,nome,ent){
  var audio=document.getElementById('pl-audio');
  _plLista=getListaPontos();_plIdx=_plLista.findIndex(function(p){return p.url===url;});
  if(_plIdx<0){_plLista.push({url:url,nome:nome,ent:ent});_plIdx=_plLista.length-1;}
  document.querySelectorAll('.audio-card').forEach(function(c){c.classList.remove('playing');});
  audio.src=url;audio.play();_plTocando=true;
  document.getElementById('pl-play').innerHTML='&#9646;&#9646;';
  document.getElementById('pl-nome').textContent=nome;
  document.getElementById('pl-ent').textContent=ent;
  document.getElementById('mini-player').classList.add('ativo');
  _iniciarProgPl();
}
function plToggle(){var a=document.getElementById('pl-audio');if(_plTocando){a.pause();_plTocando=false;document.getElementById('pl-play').innerHTML='&#9654;';clearInterval(_plTimer);}else{a.play();_plTocando=true;document.getElementById('pl-play').innerHTML='&#9646;&#9646;';_iniciarProgPl();}}
function plProximo(){if(_plLista.length){_plIdx=(_plIdx+1)%_plLista.length;var p=_plLista[_plIdx];plTocar(p.url,p.nome,p.ent);}}
function plAnterior(){if(_plLista.length){_plIdx=(_plIdx-1+_plLista.length)%_plLista.length;var p=_plLista[_plIdx];plTocar(p.url,p.nome,p.ent);}}
function plFechar(){var a=document.getElementById('pl-audio');a.pause();_plTocando=false;_plIdx=-1;document.getElementById('mini-player').classList.remove('ativo');clearInterval(_plTimer);document.querySelectorAll('.audio-card').forEach(function(c){c.classList.remove('playing');});}
function seekPl(e){var a=document.getElementById('pl-audio'),b=document.getElementById('pl-barra');if(!a.duration)return;a.currentTime=(e.clientX-b.getBoundingClientRect().left)/b.offsetWidth*a.duration;}
function _iniciarProgPl(){clearInterval(_plTimer);var a=document.getElementById('pl-audio');_plTimer=setInterval(function(){if(!a.duration)return;document.getElementById('pl-prog').style.width=(a.currentTime/a.duration*100)+'%';var f=function(s){return Math.floor(s/60)+':'+(Math.floor(s%60)<10?'0':'')+Math.floor(s%60);};document.getElementById('pl-tempo').textContent=f(a.currentTime)+' / '+f(a.duration);},500);a.onended=function(){plProximo();};}


